import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {
  // Asegura el contenedor
  if (!input.tsl_wo_work_order_attribute) {
    input.tsl_wo_work_order_attribute = {};
  }
  const workOrder = input.tsl_wo_work_order_attribute;

  // Asegura el objeto billing_items con la forma correcta
  if (!workOrder.billing_items) {
    workOrder.billing_items = {
      active_energy_billing_items: [],
      public_lighting_billing_items: null,
      cleaning_billing_items: null,
    };
  }

  // Si existe pero la lista está en null, inicialízala como []
  if (workOrder.billing_items.active_energy_billing_items == null) {
    workOrder.billing_items.active_energy_billing_items = [];
  }

  // Item a agregar
  const newItem = {
    legacy_billing_item_id: null,
    billing_item_amount: 0.0,
    is_calculate: "true",
    billing_item_code: "subsidio",
    billing_item_description: "Subsido",
    print_description: "Subsidio",
    print_order: 59,
    calculation_order: 59,
    print_grouping: null,
    method : 'AFINIA-EN001-ENRE001-METODOS DE CALCULO-SUBSIDIO'
  };

  // Agrega al arreglo correcto
  workOrder.billing_items.active_energy_billing_items.push(newItem);

  return input;
};

